def sp(id, kind, name, when, image_ids, spot_it, story_md, why, hook, source_ids, where=None, native_name=None, compare=None, media_ids=None):
    d = {"id": id, "kind": kind, "name": name}
    if native_name:
        d["native_name"] = native_name
    if where:
        d["where"] = {"label": where[0], "lat": where[1], "lon": where[2]}
    d.update({"when": when, "image_ids": image_ids, "media_ids": media_ids or [], "spot_it": spot_it,
              "story_md": story_md, "why_it_matters": why, "memory_hook": hook, "source_ids": source_ids})
    if compare:
        d["compare"] = compare
    return d

